// Runtime view of player-prop-crosswalk.json (Kalshi KXNFLTD/KXMLBHR player ticker ->
// verified Polymarket US astatc player market). Generated by scripts/gen-prop-crosswalk.js
// from REAL Kalshi events + Poly event markets: same game (ET date, teams, MLB first-pitch
// clock), same team, same FULL player name. Anything not listed is UNMAPPED.
'use strict';
let data;
try { data = require('./player-prop-crosswalk.json'); } catch (e) { data = { players: [] }; }

function nname(s) {
  return String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
    .replace(/[.'’`]/g, '').replace(/[^a-z0-9]+/g, ' ').trim();
}

function index(players) {
  const byKalshi = new Map(); const byPoly = new Map();
  for (const p of players || []) {
    const kk = String(p.k).toUpperCase();
    const pk = `${p.poly.stem}|${p.poly.abbr}`;
    // Defensive: a duplicate on either side makes BOTH entries unusable.
    if (byKalshi.has(kk) || byPoly.has(pk)) { byKalshi.set(kk, null); byPoly.set(pk, null); continue; }
    byKalshi.set(kk, p); byPoly.set(pk, p);
  }
  return { byKalshi, byPoly };
}
const base = index(data.players);

module.exports = {
  nname,
  index,
  byKalshi: (k, idx) => (idx || base).byKalshi.get(String(k).toUpperCase()) || null,
  byPoly: (stem, abbr, idx) => (idx || base).byPoly.get(`${stem}|${abbr}`) || null,
  size: () => base.byKalshi.size,
};
